import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene transform
  const pos = config.scenePosition || [3.2, -0.3, 0];
  const rot = config.sceneRotation || [0, 0, 0];
  const scl = config.sceneScale || [1, 1, 1];

  group.position.set(...pos);
  group.rotation.set(...rot);
  group.scale.set(...scl);

  // Load texture
  const imageUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Calculate plane dimensions from atlas aspect ratio
  const atlas = config.atlasRegion || { w: 512, h: 320 };
  const aspect = atlas.w / atlas.h;
  const geometry = new THREE.PlaneGeometry(2.0, 2.0 / aspect);

  // Create material with texture node
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = new THREE.TextureNode(texture);
  material.transparent = true;

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Initialize handlers
  group.userData.handlers = {};

  let hoverTl = null;
  let pressTl = null;
  const origY = pos[1];

  // Hover handler: rise-in preset (0.15 scene units)
  group.userData.handlers.onHover = (hovering) => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(group.position, {
      y: hovering ? origY + 0.15 : origY,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  // Click handler: emit hub-journal.select event
  group.userData.handlers.onClick = () => {
    const click = config.behaviorSpec?.interactions?.find(i => i.event === 'click');
    if (click?.effect?.startsWith('emit:')) {
      const event = click.effect.slice(5);
      group.dispatchEvent({ type: 'node-event', detail: { event } });
    }
  };

  // Press handler: scale down to 0.97
  group.userData.handlers.onPress = (pressing) => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.to(mesh.scale, {
      x: pressing ? 0.97 : 1,
      y: pressing ? 0.97 : 1,
      duration: 0.12,
      ease: 'back.out'
    });
  };

  // Stock badge handler: update opacity based on inventory status
  group.userData.handlers.updateStockBadge = (inStock) => {
    group.userData.inStock = inStock;
    material.opacity = inStock ? 1.0 : 0.6;
  };

  // Cleanup: dispose resources and kill timelines
  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
